`ifndef XIL_XECLIB
  reg attr_test;
  reg attr_err;
  
  initial begin
  trig_attr = 1'b0;
  `ifdef XIL_ATTR_TEST
    attr_test = 1'b1;
  `else
    attr_test = 1'b0;
  `endif
    attr_err = 1'b0;
    #1;
    trig_attr = ~trig_attr;
  end
`endif

`ifndef XIL_XECLIB
  always @ (trig_attr) begin
    #1;
    if ((attr_test == 1'b1) ||
        ((CLKDIV0_REG != 2) &&
         (CLKDIV0_REG != 1) &&
         (CLKDIV0_REG != 4) &&
         (CLKDIV0_REG != 8))) begin
      $display("Error: [Unisim %s-101] CLKDIV0 attribute is set to %d.  Legal values for this attribute are 2, 1, 4 or 8. Instance: %m", MODULE_NAME, CLKDIV0_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((CLKDIV1_REG != 2) &&
         (CLKDIV1_REG != 1) &&
         (CLKDIV1_REG != 4) &&
         (CLKDIV1_REG != 8))) begin
      $display("Error: [Unisim %s-102] CLKDIV1 attribute is set to %d.  Legal values for this attribute are 2, 1, 4 or 8. Instance: %m", MODULE_NAME, CLKDIV1_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((CPM5_DPLL0INT_DIVOUT_REG != 8) &&
         (CPM5_DPLL0INT_DIVOUT_REG != 1) &&
         (CPM5_DPLL0INT_DIVOUT_REG != 2) &&
         (CPM5_DPLL0INT_DIVOUT_REG != 4))) begin
      $display("Error: [Unisim %s-103] CPM5_DPLL0INT_DIVOUT attribute is set to %d.  Legal values for this attribute are 8, 1, 2 or 4. Instance: %m", MODULE_NAME, CPM5_DPLL0INT_DIVOUT_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((CPM5_DPLL1INT_DIVOUT_REG != 8) &&
         (CPM5_DPLL1INT_DIVOUT_REG != 1) &&
         (CPM5_DPLL1INT_DIVOUT_REG != 2) &&
         (CPM5_DPLL1INT_DIVOUT_REG != 4))) begin
      $display("Error: [Unisim %s-104] CPM5_DPLL1INT_DIVOUT attribute is set to %d.  Legal values for this attribute are 8, 1, 2 or 4. Instance: %m", MODULE_NAME, CPM5_DPLL1INT_DIVOUT_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((CPM5_MODE_0_REG != "NONE") &&
         (CPM5_MODE_0_REG != "CPM5_CCIX") &&
         (CPM5_MODE_0_REG != "CPM5_CCIX_L2") &&
         (CPM5_MODE_0_REG != "CPM5_DMA") &&
         (CPM5_MODE_0_REG != "CPM5_PCIESTREAM"))) begin
      $display("Error: [Unisim %s-105] CPM5_MODE_0 attribute is set to %s.  Legal values for this attribute are NONE, CPM5_CCIX, CPM5_CCIX_L2, CPM5_DMA or CPM5_PCIESTREAM. Instance: %m", MODULE_NAME, CPM5_MODE_0_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((CPM5_MODE_1_REG != "NONE") &&
         (CPM5_MODE_1_REG != "CPM5_CCIX") &&
         (CPM5_MODE_1_REG != "CPM5_CCIX_L2") &&
         (CPM5_MODE_1_REG != "CPM5_DMA") &&
         (CPM5_MODE_1_REG != "CPM5_PCIESTREAM"))) begin
      $display("Error: [Unisim %s-106] CPM5_MODE_1 attribute is set to %s.  Legal values for this attribute are NONE, CPM5_CCIX, CPM5_CCIX_L2, CPM5_DMA or CPM5_PCIESTREAM. Instance: %m", MODULE_NAME, CPM5_MODE_1_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((CXS0_MODE_REG != "CHI_AXI") &&
         (CXS0_MODE_REG != "CXS"))) begin
      $display("Error: [Unisim %s-107] CXS0_MODE attribute is set to %s.  Legal values for this attribute are CHI_AXI or CXS. Instance: %m", MODULE_NAME, CXS0_MODE_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((CXS1_MODE_REG != "CHI_AXI") &&
         (CXS1_MODE_REG != "CXS"))) begin
      $display("Error: [Unisim %s-108] CXS1_MODE attribute is set to %s.  Legal values for this attribute are CHI_AXI or CXS. Instance: %m", MODULE_NAME, CXS1_MODE_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((DPLL0_DESKEW_DELAY_REG < 0) || (DPLL0_DESKEW_DELAY_REG > 63))) begin
      $display("Error: [Unisim %s-109] DPLL0_DESKEW_DELAY attribute is set to %d.  Legal values for this attribute are 0 to 63. Instance: %m", MODULE_NAME, DPLL0_DESKEW_DELAY_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((DPLL0_DESKEW_DELAY_EN_REG != "FALSE") &&
         (DPLL0_DESKEW_DELAY_EN_REG != "TRUE"))) begin
      $display("Error: [Unisim %s-110] DPLL0_DESKEW_DELAY_EN attribute is set to %s.  Legal values for this attribute are FALSE or TRUE. Instance: %m", MODULE_NAME, DPLL0_DESKEW_DELAY_EN_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((DPLL0_DESKEW_DELAY_PATH_REG != "FALSE") &&
         (DPLL0_DESKEW_DELAY_PATH_REG != "TRUE"))) begin
      $display("Error: [Unisim %s-111] DPLL0_DESKEW_DELAY_PATH attribute is set to %s.  Legal values for this attribute are FALSE or TRUE. Instance: %m", MODULE_NAME, DPLL0_DESKEW_DELAY_PATH_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((DPLL0_DESKEW_EN_REG != "FALSE") &&
         (DPLL0_DESKEW_EN_REG != "TRUE"))) begin
      $display("Error: [Unisim %s-112] DPLL0_DESKEW_EN attribute is set to %s.  Legal values for this attribute are FALSE or TRUE. Instance: %m", MODULE_NAME, DPLL0_DESKEW_EN_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((DPLL1_DESKEW_DELAY_REG < 0) || (DPLL1_DESKEW_DELAY_REG > 63))) begin
      $display("Error: [Unisim %s-113] DPLL1_DESKEW_DELAY attribute is set to %d.  Legal values for this attribute are 0 to 63. Instance: %m", MODULE_NAME, DPLL1_DESKEW_DELAY_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((DPLL1_DESKEW_DELAY_EN_REG != "FALSE") &&
         (DPLL1_DESKEW_DELAY_EN_REG != "TRUE"))) begin
      $display("Error: [Unisim %s-114] DPLL1_DESKEW_DELAY_EN attribute is set to %s.  Legal values for this attribute are FALSE or TRUE. Instance: %m", MODULE_NAME, DPLL1_DESKEW_DELAY_EN_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((DPLL1_DESKEW_DELAY_PATH_REG != "FALSE") &&
         (DPLL1_DESKEW_DELAY_PATH_REG != "TRUE"))) begin
      $display("Error: [Unisim %s-115] DPLL1_DESKEW_DELAY_PATH attribute is set to %s.  Legal values for this attribute are FALSE or TRUE. Instance: %m", MODULE_NAME, DPLL1_DESKEW_DELAY_PATH_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((DPLL1_DESKEW_EN_REG != "FALSE") &&
         (DPLL1_DESKEW_EN_REG != "TRUE"))) begin
      $display("Error: [Unisim %s-116] DPLL1_DESKEW_EN attribute is set to %s.  Legal values for this attribute are FALSE or TRUE. Instance: %m", MODULE_NAME, DPLL1_DESKEW_EN_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((LINK_SPEED_0_REG != "GEN2") &&
         (LINK_SPEED_0_REG != "ESM20G") &&
         (LINK_SPEED_0_REG != "ESM25G") &&
         (LINK_SPEED_0_REG != "GEN3") &&
         (LINK_SPEED_0_REG != "GEN4") &&
         (LINK_SPEED_0_REG != "GEN5"))) begin
      $display("Error: [Unisim %s-117] LINK_SPEED_0 attribute is set to %s.  Legal values for this attribute are GEN2, ESM20G, ESM25G, GEN3, GEN4 or GEN5. Instance: %m", MODULE_NAME, LINK_SPEED_0_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((LINK_SPEED_1_REG != "GEN2") &&
         (LINK_SPEED_1_REG != "ESM20G") &&
         (LINK_SPEED_1_REG != "ESM25G") &&
         (LINK_SPEED_1_REG != "GEN3") &&
         (LINK_SPEED_1_REG != "GEN4") &&
         (LINK_SPEED_1_REG != "GEN5"))) begin
      $display("Error: [Unisim %s-118] LINK_SPEED_1 attribute is set to %s.  Legal values for this attribute are GEN2, ESM20G, ESM25G, GEN3, GEN4 or GEN5. Instance: %m", MODULE_NAME, LINK_SPEED_1_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((LINK_WIDTH_0_REG != 2) &&
         (LINK_WIDTH_0_REG != 4) &&
         (LINK_WIDTH_0_REG != 8) &&
         (LINK_WIDTH_0_REG != 16))) begin
      $display("Error: [Unisim %s-119] LINK_WIDTH_0 attribute is set to %d.  Legal values for this attribute are 2, 4, 8 or 16. Instance: %m", MODULE_NAME, LINK_WIDTH_0_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((LINK_WIDTH_1_REG != 2) &&
         (LINK_WIDTH_1_REG != 4) &&
         (LINK_WIDTH_1_REG != 8))) begin
      $display("Error: [Unisim %s-120] LINK_WIDTH_1 attribute is set to %d.  Legal values for this attribute are 2, 4 or 8. Instance: %m", MODULE_NAME, LINK_WIDTH_1_REG);
      attr_err = 1'b1;
    end
    
    if (attr_err == 1'b1) #1 $finish;
  end
`endif


